import type { Question } from "./question-types";

/**
 * Text of supabase/gabarito.sql: the server's copy of the answer key, used by the ranking
 * (registrar_respostas). Only id, right alternative, number of alternatives and level — no
 * statement. Generated by `bun run gabarito`; a test checks it is up to date.
 */
export function gabaritoSQL(questions: Question[]): string {
  const quote = (s: string) => `'${s.replace(/'/g, "''")}'`;
  const rows = [...questions]
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    .map((q) => `  (${quote(q.id)}, ${q.answer}, ${q.options.length}, ${quote(q.level)})`);
  return [
    "-- Reta Enem — gabarito do ranking (fase 12). GERADO por `bun run gabarito`: não edite à mão.",
    "-- Rode no SQL Editor do Supabase depois do 0003_ranking.sql e sempre que questões entrarem no banco.",
    `-- ${questions.length} questões.`,
    "insert into public.gabarito (questao, resposta, alternativas, nivel) values",
    rows.join(",\n"),
    "on conflict (questao) do update set",
    "  resposta = excluded.resposta, alternativas = excluded.alternativas, nivel = excluded.nivel;",
    "",
  ].join("\n");
}
